CREATE TABLE "Components" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(100) NOT NULL,
    "Aliases" text[] NOT NULL,
    "RelatedGroupIds" integer[] NOT NULL,
    CONSTRAINT "PK_Components" PRIMARY KEY ("Id")
);


CREATE TABLE "Users" (
    "Id" uuid NOT NULL,
    "Email" character varying(254) NOT NULL,
    "NormalizedEmail" character varying(254) NOT NULL,
    "PasswordHash" text NOT NULL,
    "DisplayName" character varying(80) NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_Users" PRIMARY KEY ("Id")
);


CREATE TABLE "Analyses" (
    "Id" uuid NOT NULL,
    "UserId" uuid NOT NULL,
    "ParentAnalysisId" uuid,
    "CreatedAt" timestamp with time zone NOT NULL,
    "ProductName" character varying(120) NOT NULL,
    "Source" text NOT NULL,
    "RawText" text NOT NULL,
    "Status" text NOT NULL,
    "Model" text NOT NULL,
    "ResultJson" text NOT NULL,
    CONSTRAINT "PK_Analyses" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Analyses_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE CASCADE
);


CREATE TABLE "RefreshSessions" (
    "Id" uuid NOT NULL,
    "UserId" uuid NOT NULL,
    "TokenHash" character varying(64) NOT NULL,
    "ExpiresAt" timestamp with time zone NOT NULL,
    "Version" integer NOT NULL,
    CONSTRAINT "PK_RefreshSessions" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_RefreshSessions_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE CASCADE
);


CREATE TABLE "TrackedComponents" (
    "UserId" uuid NOT NULL,
    "ComponentId" integer NOT NULL,
    "Reason" integer NOT NULL,
    "Note" character varying(300) NOT NULL,
    CONSTRAINT "PK_TrackedComponents" PRIMARY KEY ("UserId", "ComponentId"),
    CONSTRAINT "FK_TrackedComponents_Components_ComponentId" FOREIGN KEY ("ComponentId") REFERENCES "Components" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_TrackedComponents_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE CASCADE
);


