CREATE INDEX "IX_Analyses_UserId_CreatedAt" ON "Analyses" ("UserId", "CreatedAt");


CREATE UNIQUE INDEX "IX_RefreshSessions_TokenHash" ON "RefreshSessions" ("TokenHash");


CREATE INDEX "IX_RefreshSessions_UserId" ON "RefreshSessions" ("UserId");


CREATE INDEX "IX_TrackedComponents_ComponentId" ON "TrackedComponents" ("ComponentId");


CREATE UNIQUE INDEX "IX_Users_NormalizedEmail" ON "Users" ("NormalizedEmail");


SELECT setval(
    pg_get_serial_sequence('"Components"', 'Id'),
    GREATEST(
        (SELECT MAX("Id") FROM "Components") + 1,
        nextval(pg_get_serial_sequence('"Components"', 'Id'))),
    false);


